    type Err = String;
    fn from_str(value: &str) -> Result<Self, Self::Err> {
        let id = value
            .parse::<u32>()
            .map_err(|_| "Invalid MP ID".to_string())?;
        if id == 0 || i32::try_from(id).is_err() {
            return Err("Invalid MP ID".to_string());
        }
        Ok(Self(id))
